import re

class WalletAddressValidator:
    """
    A class to validate cryptocurrency wallet addresses.
    """

    # Define regex patterns for different cryptocurrency wallet addresses
    patterns = {
        'bitcoin': r'^[13][a-km-zA-HJ-NP-Z1-9]{25,34}$',
        'ethereum': r'^0x[a-fA-F0-9]{40}$',
        'litecoin': r'^[LM3][a-km-zA-HJ-NP-Z1-9]{26,33}$',
        # Add more patterns for other cryptocurrencies as needed
    }

    @staticmethod
    def validate_address(address: str, currency: str) -> bool:
        """
        Validate a wallet address against the specified cryptocurrency pattern.

        :param address: The wallet address to validate.
        :param currency: The type of cryptocurrency (e.g., 'bitcoin', 'ethereum').
        :return: True if the address is valid, False otherwise.
        :raises ValueError: If the currency is not supported.
        """
        # Check if the currency is supported
        if currency not in WalletAddressValidator.patterns:
            raise ValueError(f"Unsupported currency: {currency}")

        # Get the regex pattern for the specified currency
        pattern = WalletAddressValidator.patterns[currency]

        # Validate the address using regex
        is_valid = re.match(pattern, address) is not None
        return is_valid

